export function createRabbitPolishedSfx(m){const seen=new Set();return{accept(events){for(const e of events){if(!['rabbitCarrotImpact','rabbitMutinyImpact','rabbitChildStunned'].includes(e.type)||e.version!==2||typeof e.id!=='string'||!e.id.startsWith(e.type+':')||seen.has(e.id))continue;if(seen.size>=128)seen.delete(seen.values().next().value);seen.add(e.id);if(!m.enabled||!m.ctx||m.ctx.state&&m.ctx.state!=='running')continue;const prior=m.effectChannel,t=m.ctx.currentTime,tone=(f,d,v=.04,delay=0,to=f)=>m.tone(f,d,'sine',v,t+delay,to,.005,true);m.effectChannel=true;try{if(e.type==='rabbitCarrotImpact'){tone(130,.16,.07,0,50);m.noise(.11,.04,t,600);for(let i=0;i<3;i++)m.noise(.025,.013,t+.04+i*.04,1000+i*350);}else if(e.type==='rabbitMutinyImpact'){tone(165,.13,.055,0,90);tone(440,.12,.02,.04,620);m.noise(.07,.026,t,850);}else tone(390,.09,.026,0,220);}finally{m.effectChannel=prior;}}},reset(){seen.clear();}};}
